"use client"

import type { StandardSchemaV1 } from "@standard-schema/spec"
import { useId, useRef, useState, type ComponentType, type ReactNode } from "react"
import type { FieldValues, Path, UseFormReturn } from "react-hook-form"

import { Button } from "@/components/ui/button"
import {
  Form,
  FormActions,
  FormRootError,
  toFormErrors,
  useFormInstance,
  type FormProps,
  type FormValuesOf,
} from "@/components/ui/form"
import { useFormContext } from "@/components/ui/form-context"
import { StepFormProgress } from "@/components/ui/step-form-progress"
import { useHeadingFocus, useSeenFields, useSubmitInterceptor } from "@/components/ui/use-step-form"
import { cn } from "@/lib/utils"

type FormStep<Values extends FieldValues = FieldValues> = {
  /** Stable id, reported by `onStepChange` and accepted by `step` and `defaultStep`. */
  id: string
  title: ReactNode
  description?: ReactNode
  /** The step's fields, usually `FormField`s; the form instance is there for `watch`-free logic like `getValues`. */
  render: (form: UseFormReturn<Values>) => ReactNode
  /** The fields Next validates; the step's mounted `FormField`s by default. */
  fields?: readonly Path<Values>[]
  /**
   * Runs once the step's fields are valid, before moving on. Return nothing to continue, or an error in any shape
   * `onSubmit` may throw (`{ fieldErrors, message }`, a string, a `FormServerError`) to stay.
   */
  validate?: (values: Values) => unknown
}

type StepDirection = "next" | "back" | "error"

type StepChangeDetails = {
  index: number
  /** The step it leaves. */
  previous: string
  /** `error` when a failed submit returns to the step that holds the first invalid field. */
  direction: StepDirection
}

type StepFormLabels = {
  next?: ReactNode
  back?: ReactNode
  submit?: ReactNode
  /** Names the progress list for screen readers. */
  progress?: string
}

type StepFormProps<Schema extends StandardSchemaV1> = Omit<FormProps<Schema>, "children"> & {
  steps: readonly FormStep<FormValuesOf<Schema>>[]
  /** The current step's id, controlled. */
  step?: string
  defaultStep?: string
  onStepChange?: (step: string, details: StepChangeDetails) => void
  /** Button and progress labels in the page's language; English by default. */
  labels?: StepFormLabels
  /** What screen readers hear once a submit or a step's `validate` has been pending for a second. */
  pendingLabel?: string
  headingLevel?: 2 | 3 | 4
  rootErrorTitle?: ReactNode
}

type StepFormFrameProps<Schema extends StandardSchemaV1> = StepFormProps<Schema> & {
  cancel?: ReactNode
  onCancel?: () => void
  body?: ComponentType<{ children?: ReactNode }>
  actionsClassName?: string
}

/** A new object for every move, so moving to the same direction twice still runs the focus effect. */
type StepMove = { direction: StepDirection }

function errorPaths(errors: Record<string, unknown>, prefix = ""): string[] {
  return Object.entries(errors).flatMap(([key, value]) => {
    if (!value || typeof value !== "object") return []
    const path = prefix ? `${prefix}.${key}` : key
    return "type" in value || "message" in value ? [path] : errorPaths(value as Record<string, unknown>, path)
  })
}

const related = (a: string, b: string) => a === b || a.startsWith(`${b}.`) || b.startsWith(`${a}.`)

function DefaultBody({ children }: { children?: ReactNode }) {
  return <div className="flex min-w-0 flex-col gap-group">{children}</div>
}

type ContentProps = {
  steps: readonly FormStep[]
  index: number
  move: StepMove | null
  go: (target: number, direction: StepDirection) => void
  labels?: StepFormLabels
  pendingLabel?: string
  headingLevel: 2 | 3 | 4
  rootErrorTitle?: ReactNode
  cancel?: ReactNode
  onCancel?: () => void
  Body: ComponentType<{ children?: ReactNode }>
  actionsClassName?: string
}

function StepFormContent({
  steps,
  index,
  move,
  go,
  labels,
  pendingLabel,
  headingLevel,
  rootErrorTitle,
  cancel,
  onCancel,
  Body,
  actionsClassName,
}: ContentProps) {
  const form = useFormInstance()
  const context = useFormContext("StepForm")
  const step = steps[index]!
  const last = index === steps.length - 1
  const headingId = useId()
  const heading = useRef<HTMLHeadingElement>(null)
  const seen = useRef(new Map<string, string[]>())
  const [validating, setValidating] = useState(false)
  const Heading = `h${headingLevel}` as const

  useSeenFields(seen, step.id, context.fields)
  useHeadingFocus(move, heading)

  const stepOf = (paths: string[]) => {
    const found = steps.findIndex((candidate) => {
      const names = candidate.fields ?? seen.current.get(candidate.id) ?? []
      return paths.some((path) => names.some((name) => related(path, name)))
    })
    if (found >= 0) return found
    // A step never shown (after `defaultStep`) and without `fields` is the only place the field can be.
    const unknown = steps.findIndex((candidate) => !candidate.fields && !seen.current.has(candidate.id))
    return unknown < 0 ? index : unknown
  }

  const next = async () => {
    form.clearErrors("root")
    const names = step.fields ?? [...context.fields.keys()]
    const validate = async () => {
      if (names.length > 0 && !(await form.trigger(names))) return context.requestFocus()
      const problem = await step.validate?.(form.getValues())
      if (problem !== undefined && problem !== null) {
        context.applyError(problem)
        return context.requestFocus()
      }
      go(index + 1, "next")
    }
    setValidating(true)
    // A promise's finally, not a try/finally block: React Compiler 1.0 can't compile a component that has one.
    return validate().finally(() => setValidating(false))
  }

  useSubmitInterceptor(context.setInterceptor, {
    beforeSubmit: async () => {
      if (last) return true
      await next()
      return false
    },
    onInvalid: (errors) => go(stepOf(errorPaths(errors)), "error"),
    onError: (error) => go(stepOf(Object.keys(toFormErrors(error)?.fieldErrors ?? {})), "error"),
  })

  return (
    <>
      <StepFormProgress steps={steps} current={index} label={labels?.progress ?? "Progress"} />
      <Body>
        <section aria-labelledby={headingId} data-slot="step-form-step" className="flex min-w-0 flex-col gap-group">
          <div className="flex flex-col gap-inline">
            <Heading
              ref={heading}
              id={headingId}
              tabIndex={-1}
              data-slot="step-form-title"
              className="text-title-sm tracking-tight focus:outline-none"
            >
              {step.title}
            </Heading>
            {step.description === undefined ? null : (
              <p className="text-body-sm text-muted-foreground">{step.description}</p>
            )}
          </div>
          {step.render(form)}
        </section>
        <FormRootError title={rootErrorTitle} />
      </Body>
      <FormActions
        submitLabel={last ? (labels?.submit ?? "Submit") : (labels?.next ?? "Next")}
        pendingLabel={pendingLabel}
        pending={validating}
        cancel={cancel}
        onCancel={onCancel}
        secondaryAction={
          index === 0 ? null : (
            <Button
              type="button"
              variant="ghost"
              disabled={context.pending || validating}
              onClick={() => go(index - 1, "back")}
            >
              {labels?.back ?? "Back"}
            </Button>
          )
        }
        className={actionsClassName}
      />
    </>
  )
}

function StepFormFrame<Schema extends StandardSchemaV1>({
  steps,
  step: stepProp,
  defaultStep,
  onStepChange,
  labels,
  pendingLabel,
  headingLevel = 2,
  rootErrorTitle,
  cancel,
  onCancel,
  body = DefaultBody,
  actionsClassName,
  className,
  ...form
}: StepFormFrameProps<Schema>) {
  const [ownStep, setOwnStep] = useState(() => defaultStep ?? steps[0]?.id)
  const [move, setMove] = useState<StepMove | null>(null)
  const current = stepProp ?? ownStep
  const index = Math.max(
    0,
    steps.findIndex((candidate) => candidate.id === current),
  )

  const go = (target: number, direction: StepDirection) => {
    const destination = steps[target]
    if (!destination || target === index) return
    setMove({ direction })
    if (stepProp === undefined) setOwnStep(destination.id)
    onStepChange?.(destination.id, { index: target, previous: steps[index]!.id, direction })
  }

  return (
    <Form {...form} className={cn("min-w-0", className)}>
      <StepFormContent
        steps={steps as readonly FormStep[]}
        index={index}
        move={move}
        go={go}
        labels={labels}
        pendingLabel={pendingLabel}
        headingLevel={headingLevel}
        rootErrorTitle={rootErrorTitle}
        cancel={cancel}
        onCancel={onCancel}
        Body={body}
        actionsClassName={actionsClassName}
      />
    </Form>
  )
}

/**
 * A multi-step form: one schema, one step's fields at a time. Next (or Enter) validates only that step, Back keeps
 * every value, and the last step submits everything through `onSubmit`, with the same error mapping as `Form`.
 */
function StepForm<Schema extends StandardSchemaV1>(props: StepFormProps<Schema>) {
  return <StepFormFrame {...props} />
}

export { StepForm, StepFormFrame }
export type { FormStep, StepChangeDetails, StepDirection, StepFormLabels, StepFormProps }

import type { ReactNode } from "react"
import { CheckIcon } from "lucide-react"

import { cn } from "@/lib/utils"

type StepState = "complete" | "current" | "upcoming"

const markerClassName: Record<StepState, string> = {
  complete: "border-primary bg-primary text-primary-foreground",
  current: "border-primary bg-background text-foreground ring-2 ring-ring",
  upcoming: "border-input-strong bg-background text-muted-foreground",
}

const titleClassName: Record<StepState, string> = {
  complete: "text-muted-foreground",
  current: "font-medium text-foreground",
  upcoming: "text-muted-foreground narrow:sr-only",
}

type StepFormProgressProps = {
  steps: readonly { id: string; title: ReactNode }[]
  current: number
  /** Names the list for screen readers, in the page's language. */
  label: string
  className?: string
}

/** Where the wizard is: an ordered list, the current step marked with `aria-current="step"`. */
function StepFormProgress({ steps, current, label, className }: StepFormProgressProps) {
  return (
    <ol
      aria-label={label}
      data-slot="step-form-progress"
      className={cn("flex min-w-0 flex-wrap items-center gap-items text-body-sm", className)}
    >
      {steps.map((step, index) => {
        const state: StepState = index < current ? "complete" : index === current ? "current" : "upcoming"
        return (
          <li
            key={step.id}
            data-state={state}
            aria-current={state === "current" ? "step" : undefined}
            className="flex min-w-0 items-center gap-inline"
          >
            {index === 0 ? null : <span aria-hidden="true" className="h-px w-4 shrink-0 bg-border" />}
            <span
              aria-hidden="true"
              className={cn(
                "flex size-6 shrink-0 items-center justify-center rounded-full border font-mono text-caption",
                markerClassName[state],
              )}
            >
              {state === "complete" ? <CheckIcon strokeWidth={2.5} className="size-3.5" /> : index + 1}
            </span>
            <span className={cn("truncate", titleClassName[state])}>{step.title}</span>
          </li>
        )
      })}
    </ol>
  )
}

export { StepFormProgress }
export type { StepFormProgressProps }

"use client"

import type { StandardSchemaV1 } from "@standard-schema/spec"
import type { DialogOpenChangeReason } from "@ui-sdk/react/dialog"
import type { VariantProps } from "class-variance-authority"
import { useId, useRef, useState, type ComponentProps, type ReactNode } from "react"
import type { FieldValues } from "react-hook-form"

import { Button, type buttonVariants } from "@/components/ui/button"
import {
  Dialog,
  DialogBackdrop,
  DialogBody,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
  type DialogSize,
} from "@/components/ui/dialog"
import type { FormSubmitHelpers } from "@/components/ui/form"
import {
  StepFormFrame,
  type StepFormLabels,
  type StepFormProps,
  StepForm,
  type FormStep,
  type StepChangeDetails,
  type StepDirection,
} from "@/components/ui/step-form"
import { useFocusFirstStepOnRestart } from "@/components/ui/use-step-dialog-focus"
import { cn } from "@/lib/utils"

type StepDialogLabels = StepFormLabels & {
  /** The button that closes the dialog; "Cancel" by default. */
  cancel?: ReactNode
  /** The button that closes the result step; "Done" by default. */
  done?: ReactNode
}

/**
 * Why the dialog opened or closed: `submit` once `onSubmit` resolved (without a `resultStep`), `done` from the result
 * step's Done button or its `close`, `cancel` from the Cancel button, `escape`, `outside` (a press outside it),
 * `dismiss` for any other dismissal, `trigger` when its trigger opened it, and `imperative` when `open` changed it.
 */
type StepDialogOpenChangeReason =
  | "submit"
  | "done"
  | "cancel"
  | "dismiss"
  | "escape"
  | "outside"
  | "trigger"
  | "imperative"

type StepDialogOpenChangeDetails = {
  reason: StepDialogOpenChangeReason
  /** UI SDK's own reason, when the Dialog reported the change. */
  dialogReason?: DialogOpenChangeReason
}

type StepDialogResultActions = {
  /** Closes the dialog, with the `done` reason. */
  close: () => void
  /** Starts over from the first step with the default values. */
  restart: () => void
}

type StepDialogResultStep<Result> = {
  /** The result's heading, which takes focus when it shows. */
  title: ReactNode
  /** What `onSubmit` resolved with, and the result step's actions. */
  render: (result: Result, actions: StepDialogResultActions) => ReactNode
}

function toReason(open: boolean, reason: DialogOpenChangeReason): StepDialogOpenChangeReason {
  if (open) return reason === "imperative" ? "imperative" : "trigger"
  if (reason === "escape-key") return "escape"
  if (reason === "outside-press") return "outside"
  if (reason === "close-press") return "cancel"
  return "dismiss"
}

type StepDialogProps<Schema extends StandardSchemaV1, Result = unknown> = Omit<
  StepFormProps<Schema>,
  "labels" | "headingLevel" | "onPendingChange" | "className" | "onSubmit"
> & {
  /** Submits every step's values. With a `resultStep`, what it resolves with is the result shown. */
  onSubmit: (
    values: StandardSchemaV1.InferOutput<Schema>,
    helpers: FormSubmitHelpers<StandardSchemaV1.InferInput<Schema> & FieldValues>,
  ) => Result | Promise<Result>
  open?: boolean
  defaultOpen?: boolean
  /** `details.reason` says why: `submit`, `done`, `cancel`, `escape`, `outside`, `dismiss`, or `trigger` when it opens. */
  onOpenChange?: (open: boolean, details: StepDialogOpenChangeDetails) => void
  /** Content of the button that opens the dialog. Omit it when opening through `open`. */
  trigger?: ReactNode
  triggerVariant?: VariantProps<typeof buttonVariants>["variant"]
  title: ReactNode
  description?: ReactNode
  size?: DialogSize
  labels?: StepDialogLabels
  /** Where focus goes once the dialog closes; the trigger by default. */
  returnFocus?: ComponentProps<typeof DialogContent>["finalFocus"]
  /** Shows what `onSubmit` resolved with inside the dialog, instead of closing it. */
  resultStep?: StepDialogResultStep<Awaited<Result>>
  className?: string
}

type Shown<Result> = { result: Result } | null

// A stable ref callback runs once, when the heading mounts.
const focusOnMount = (node: HTMLElement | null) => node?.focus()

function ResultStep<Result>({
  step,
  result,
  actions,
  doneLabel,
}: {
  step: StepDialogResultStep<Result>
  result: Result
  actions: StepDialogResultActions
  doneLabel: ReactNode
}) {
  const headingId = useId()
  return (
    <>
      <DialogBody>
        <section aria-labelledby={headingId} data-slot="step-dialog-result" className="flex min-w-0 flex-col gap-group">
          <h3
            ref={focusOnMount}
            id={headingId}
            tabIndex={-1}
            data-slot="step-dialog-result-title"
            className="text-title-sm tracking-tight focus:outline-none"
          >
            {step.title}
          </h3>
          {step.render(result, actions)}
        </section>
      </DialogBody>
      <div
        data-slot="step-dialog-result-actions"
        className="flex shrink-0 flex-wrap items-center justify-end gap-items narrow:flex-col-reverse narrow:items-stretch"
      >
        <Button type="button" onClick={actions.close}>
          {doneLabel}
        </Button>
      </div>
    </>
  )
}

/**
 * A StepForm in a Dialog: the progress and actions stay in view while the step scrolls, Escape, outside presses and
 * Cancel do nothing while submitting, and it closes once `onSubmit` resolves, or shows `resultStep` with what it
 * resolved. It starts from the first step each time it opens.
 */
function StepDialog<Schema extends StandardSchemaV1, Result = unknown>({
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  trigger,
  triggerVariant,
  title,
  description,
  size = "md",
  labels,
  returnFocus,
  resultStep,
  onSubmit,
  className,
  ...stepForm
}: StepDialogProps<Schema, Result>) {
  const [ownOpen, setOwnOpen] = useState(defaultOpen)
  const [pending, setPending] = useState(false)
  const [shown, setShown] = useState<Shown<Awaited<Result>>>(null)
  const [run, setRun] = useState(0)
  const content = useRef<HTMLDivElement>(null)
  const open = openProp ?? ownOpen

  useFocusFirstStepOnRestart(content, run)

  const setOpen = (next: boolean, details: StepDialogOpenChangeDetails) => {
    if (openProp === undefined) setOwnOpen(next)
    onOpenChange?.(next, details)
  }

  const submit: StepFormProps<Schema>["onSubmit"] = async (values, helpers) => {
    const result = await onSubmit(values, helpers)
    if (!resultStep) {
      setOpen(false, { reason: "submit" })
      return
    }
    // The form unmounts before it reports the end of the submit.
    setPending(false)
    setShown({ result })
  }

  const actions: StepDialogResultActions = {
    close: () => setOpen(false, { reason: "done" }),
    restart: () => {
      setShown(null)
      setRun((count) => count + 1)
    },
  }

  return (
    <Dialog
      open={open}
      onOpenChange={(next, details) => {
        if (!next && pending) details.cancel()
        else setOpen(next, { reason: toReason(next, details.reason), dialogReason: details.reason })
      }}
      onOpenChangeComplete={(next) => {
        if (!next) setShown(null)
      }}
      dismissible={!pending}
    >
      {trigger === undefined ? null : <DialogTrigger variant={triggerVariant}>{trigger}</DialogTrigger>}
      <DialogBackdrop />
      <DialogContent
        ref={content}
        size={size}
        finalFocus={returnFocus}
        aria-busy={pending || undefined}
        className={cn("overflow-hidden", className)}
      >
        <DialogHeader>
          <DialogTitle>{title}</DialogTitle>
          {description === undefined ? null : <DialogDescription>{description}</DialogDescription>}
        </DialogHeader>
        {shown && resultStep ? (
          <ResultStep step={resultStep} result={shown.result} actions={actions} doneLabel={labels?.done ?? "Done"} />
        ) : (
          <StepFormFrame
            key={run}
            {...stepForm}
            onSubmit={submit}
            onPendingChange={setPending}
            labels={labels}
            headingLevel={3}
            cancel={labels?.cancel ?? "Cancel"}
            onCancel={() => {
              if (!pending) setOpen(false, { reason: "cancel" })
            }}
            body={DialogBody}
            actionsClassName="shrink-0"
            className="min-h-0 flex-1"
          />
        )}
      </DialogContent>
    </Dialog>
  )
}

export { StepDialog }
export { StepForm }
export type { FormStep, StepChangeDetails, StepDirection, StepFormLabels, StepFormProps }
export type {
  StepDialogLabels,
  StepDialogOpenChangeDetails,
  StepDialogOpenChangeReason,
  StepDialogProps,
  StepDialogResultActions,
  StepDialogResultStep,
}

"use client"

import { useEffect, useEffectEvent, useLayoutEffect, type RefObject } from "react"

import type { SubmitInterceptor } from "@/components/ui/form-context"

/** After each render, records the fields the current step registered, to find the step an error belongs to. */
function useSeenFields(seenRef: RefObject<Map<string, string[]>>, stepId: string, fields: Map<string, unknown>) {
  useEffect(() => {
    seenRef.current.set(stepId, [...fields.keys()])
  })
}

/** Moves focus to the step's heading after a step forward or back, not after a jump to an error. */
function useHeadingFocus(move: { direction: string } | null, headingRef: RefObject<HTMLElement | null>) {
  useEffect(() => {
    if (move?.direction === "next" || move?.direction === "back") headingRef.current?.focus()
  }, [move, headingRef])
}

/** Hands the form this render's interceptor, so submit sees the current step, and takes it back on unmount. */
function useSubmitInterceptor(
  setInterceptor: (interceptor: SubmitInterceptor | null) => void,
  interceptor: SubmitInterceptor,
) {
  const release = useEffectEvent(() => setInterceptor(null))
  useLayoutEffect(() => {
    setInterceptor(interceptor)
  })
  useLayoutEffect(() => () => release(), [])
}

export { useHeadingFocus, useSeenFields, useSubmitInterceptor }

import { useEffect, type RefObject } from "react"

/** After a restart (`run` above 0), focus the first step's heading inside `content` once the form has remounted. */
function useFocusFirstStepOnRestart(content: RefObject<HTMLElement | null>, run: number) {
  useEffect(() => {
    if (run > 0) content.current?.querySelector<HTMLElement>('[data-slot="step-form-title"]')?.focus()
  }, [content, run])
}

export { useFocusFirstStepOnRestart }
